# Writes the hedra command files of the pancake kitchen: kitchen.txt (counter, mint stove, tiled back
# wall, shelf), burner.txt (grate and flame ring), plate.txt, bottle.txt, butter.txt, bowl.txt,
# pancake_raw/golden/dark/burnt.txt (the four looks of a cooking pancake), smoke.txt, star.txt.
# Run from models/env: /usr/bin/python3 make_env.py. Up Z, front -Y (hedra); colours exact Vanilla
# Milkshake. World (glTF) = (x, z, -y) of hedra.
HEX = {"ink": "28282e", "mauve": "6c5671", "oat": "d9c8bf", "coral": "f98284", "lilac": "b0a9e4",
       "sky": "accce4", "aqua": "b3e3da", "pink": "feaae4", "sage": "87a889", "mint": "b0eb93",
       "lime": "e9f59d", "cream": "ffe6c6", "tan": "dea38b", "apricot": "ffc384", "butter": "fff7a0",
       "milk": "fff7e4"}
def col(n, emit=False):
    h = HEX[n]; r, g, b = (int(h[i:i + 2], 16) / 255 for i in (0, 2, 4))
    s = f"--base-color {r:.4f} {g:.4f} {b:.4f}"
    return s + (f" --emission {r:.4f} {g:.4f} {b:.4f}" if emit else "")

files = {}
# ---------------------------------------------------------------- kitchen (static shell)
# counter 6.4 x 1.35 (y -0.75..0.6), top at z 0, cabinets down to z -1.9; the stove block in the
# middle (x -1.6..1.6) is mint; the wall at y 0.6 rises to z 2.3, tiled 0.4 m in a two-blue checker.
T = 0.4
tiles = []
for i in range(16):
    for j in range(6):
        if (i + j) % 2:
            x0, z0 = -3.2 + i * T, j * T
            tiles.append(f"(pos.x > {x0:.2f} && pos.x < {x0 + T:.2f} && pos.y > {z0:.2f} && pos.y < {z0 + T:.2f})")
files["kitchen"] = f"""# Kitchen shell: a cream counter with lilac cabinet fronts, a mint stove block in the middle with
# three dark knobs, a back wall of 0.4 m tiles in two pastel blues (faces of a grid picked by a
# generated expression: no texture), a cream shelf. Generated by make_env.py. Up Z, front -Y.
new
material new Counter {col('cream')} --no-slot
material new Cabinet {col('lilac')} --no-slot
material new Stove {col('mint')} --no-slot
material new StoveFront {col('sage')} --no-slot
material new Knob {col('mauve')} --no-slot
material new TileA {col('sky')} --no-slot
material new TileB {col('aqua')} --no-slot
material new Shelf {col('cream')} --no-slot
add mesh cube --name CounterL --size 1 --location -2.4 -0.075 -0.95
scale 1.6 1.35 1.9
apply --scale
add mesh cube --name CounterR --size 1 --location 2.4 -0.075 -0.95
scale 1.6 1.35 1.9
apply --scale
select CounterL CounterR
material assign Counter
material new Door {col('sky')} --no-slot
material new Oven {col('mauve')} --no-slot
select CounterL
active CounterL
mode edit
select face where "normal.y < -0.9"
material assign Cabinet
inset 0.14
material assign Door
mode object
select CounterR
active CounterR
mode edit
select face where "normal.y < -0.9"
material assign Cabinet
inset 0.14
material assign Door
mode object
add mesh cube --name StoveBox --size 1 --location 0 -0.075 -0.95
scale 3.2 1.35 1.9
apply --scale
material assign Stove
mode edit
select face where "normal.y < -0.9"
material assign StoveFront
mode object
# hidden faces still bake: the bottoms, the backs against the wall, the sides where boxes touch
select CounterL
active CounterL
mode edit
select face where "normal.z < -0.9 || normal.y > 0.9 || normal.x > 0.9"
delete only-faces
mode object
select CounterR
active CounterR
mode edit
select face where "normal.z < -0.9 || normal.y > 0.9 || normal.x < -0.9"
delete only-faces
mode object
select StoveBox
active StoveBox
mode edit
select face where "normal.z < -0.9 || normal.y > 0.9 || abs(normal.x) > 0.9"
delete only-faces
mode object
# the oven door: a dark window on the stove front, under the knobs
add mesh cube --name OvenWin --size 1 --location 0 -0.76 -1.0
scale 2.0 0.04 0.7
apply --scale
material assign Oven
add mesh cube --name OvenBar --size 1 --location 0 -0.8 -0.55
scale 1.6 0.08 0.08
apply --scale
material assign Shelf
add mesh cube --name PullL --size 1 --location -2.4 -0.8 -0.3
scale 0.5 0.08 0.08
apply --scale
add mesh cube --name PullR --size 1 --location 2.4 -0.8 -0.3
scale 0.5 0.08 0.08
apply --scale
select PullL PullR
material assign Knob
add mesh cylinder --name K0 --vertices 8 --radius 0.11 --depth 0.1 --location -1.0 -0.78 -0.3 --rotation 90 0 0
add mesh cylinder --name K1 --vertices 8 --radius 0.11 --depth 0.1 --location 0 -0.78 -0.3 --rotation 90 0 0
add mesh cylinder --name K2 --vertices 8 --radius 0.11 --depth 0.1 --location 1.0 -0.78 -0.3 --rotation 90 0 0
select K0 K1 K2
active K0
join
rename K0 Knobs
material assign Knob
add mesh grid --name Wall --x-subdivisions 16 --y-subdivisions 6 --size 1 --location 0 0 0
scale 6.4 2.4 1
apply --scale
translate 0 1.2 0
apply --location
material assign TileA
mode edit
select face where "{' || '.join(tiles)}"
material assign TileB
mode object
set rotation 90 0 0
apply --rotation
translate 0 0.6 0
apply --location
add mesh cube --name ShelfBoard --size 1 --location 0 0.45 1.55
scale 1.5 0.3 0.08
apply --scale
material assign Shelf
select all
shade flat
export kitchen.glb
"""
files["burner"] = f"""# Burner: a dark grate ring on the stove top and a ring of pastel flame just under the pan's
# edge (emissive: unlit). Origin at the stove top under the pan. Generated by make_env.py. Up Z.
new
material new Grate {col('mauve')} --no-slot
material new Flame {col('apricot', True)} --no-slot
add mesh cylinder --name Grate --vertices 12 --radius 0.36 --depth 0.04 --location 0 0 0.02
material assign Grate
add mesh torus --name Flame --major-segments 12 --minor-segments 4 --major-radius 0.4 --minor-radius 0.045 --location 0 0 0.05
material assign Flame
shade flat
select all
shade flat
export burner.glb
"""
files["plate"] = f"""# Plate: a wide shallow 12-sided dish (the served pancakes stack on it). Up Z.
new
material new Plate {col('milk')} --no-slot
add mesh cone --name Plate --vertices 12 --radius1 0.3 --radius2 0.48 --depth 0.07 --location 0 0 0.035
material assign Plate
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
shade flat
export plate.glb
"""
files["bottle"] = f"""# Syrup bottle: a pink bottle with a cream label band and a mauve cap. Up Z.
new
material new Glass {col('coral')} --no-slot
material new Label {col('cream')} --no-slot
material new Cap {col('mauve')} --no-slot
add mesh cylinder --name Body --vertices 8 --radius 0.17 --depth 0.42 --location 0 0 0.21
material assign Glass
add mesh cylinder --name Band --vertices 8 --radius 0.18 --depth 0.16 --location 0 0 0.2
material assign Label
add mesh cone --name Neck --vertices 8 --radius1 0.17 --radius2 0.07 --depth 0.16 --location 0 0 0.5
material assign Glass
add mesh cylinder --name Cap --vertices 8 --radius 0.08 --depth 0.08 --location 0 0 0.62
material assign Cap
select all
shade flat
export bottle.glb
"""
files["butter"] = f"""# Butter: a pale yellow block on a small lilac dish. Up Z.
new
material new Dish {col('lilac')} --no-slot
material new Butter {col('butter')} --no-slot
add mesh cylinder --name Dish --vertices 10 --radius 0.3 --depth 0.06 --location 0 0 0.03
material assign Dish
add mesh cube --name Block --size 1 --location 0 0 0.14
scale 0.32 0.2 0.16
apply --scale
material assign Butter
select all
shade flat
export butter.glb
"""
files["bowl"] = f"""# Batter bowl: a mint bowl full of batter, a coral whisk handle sticking out. Up Z.
new
material new Bowl {col('mint')} --no-slot
material new Batter {col('milk')} --no-slot
material new Whisk {col('coral')} --no-slot
add mesh cone --name Bowl --vertices 10 --radius1 0.2 --radius2 0.34 --depth 0.26 --location 0 0 0.13
material assign Bowl
mode edit
select face where "normal.z < -0.9"
delete only-faces
select face where "normal.z > 0.9"
material assign Batter
translate 0 0 -0.03
mode object
add mesh cube --name Whisk --size 1 --location 0.12 0.05 0.36
scale 0.07 0.07 0.42
apply --scale
set rotation 0 28 0
material assign Whisk
select all
shade flat
export bowl.glb
"""
# ---------------------------------------------------------------- pancakes: four looks, one shape
def pancake(name, top, edge):
    return f"""# Pancake ({name}): a 12-sided disc 0.54 across, 0.03 thick (it bakes ~0.1 thick: a disc spreads
# past its faces), origin at its centre so it flips about it. Generated by make_env.py. Up Z.
new
material new Top {col(top)} --no-slot
material new Edge {col(edge)} --no-slot
add mesh cylinder --name Pancake --vertices 12 --radius 0.27 --depth 0.03 --location 0 0 0
material assign Edge
mode edit
select face where "abs(normal.z) > 0.9"
material assign Top
mode object
shade flat
export pancake_{name}.glb
"""
files["pancake_raw"] = pancake("raw", "milk", "cream")
files["pancake_golden"] = pancake("golden", "apricot", "tan")
files["pancake_dark"] = pancake("dark", "tan", "mauve")
files["pancake_burnt"] = pancake("burnt", "mauve", "ink")
files["smoke"] = f"""# Smoke puff: a faceted ball (the game grows, lifts and shrinks it). Up Z.
new
material new Smoke {col('oat')} --no-slot
add mesh ico-sphere --name Puff --subdivisions 1 --radius 0.14 --location 0 0 0
material assign Smoke
shade flat
export smoke.glb
"""
files["star"] = f"""# Star: a small glowing octahedron (the perfect-flip sparkle). Up Z.
new
material new Spark {col('butter', True)} --no-slot
add mesh ico-sphere --name Star --subdivisions 1 --radius 0.07 --location 0 0 0
material assign Spark
shade flat
export star.glb
"""
for k, v in files.items():
    open(f"{k}.txt", "w").write(v)
print("wrote", ", ".join(f"{k}.txt" for k in files))
